func TestGenerateErrors(t *testing.T) {
	cases := []struct {
		name string
		mod  func(*GenerateRequest)
	}{
		{"没有地点", func(r *GenerateRequest) { r.Locations = nil }},
		{"地点过多", func(r *GenerateRequest) {
			locs := make([]string, 257)
			for i := range locs {
				locs[i] = string(rune('a'+i%26)) + string(rune('a'+i/26))
			}
			r.Locations = locs
